import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const n = Number(input[0]);
const graph: number[][] = Array.from({ length: n + 1 }, () => []);
for (let i = 1; i < n; i++) {
  const [u, v] = input[i].split(" ").map(Number);
  graph[u].push(v);
  graph[v].push(u);
}

// 頂点 1 を根として BFS で親と深さを求める
const LOG = 18; // 2^18 > 2 × 10⁵
const depth = new Int32Array(n + 1).fill(-1);
const up: Int32Array[] = Array.from({ length: LOG }, () => new Int32Array(n + 1));
depth[1] = 0;
up[0][1] = 1; // 根の親は自分自身にしておく
const queue = [1];
for (let head = 0; head < queue.length; head++) {
  const v = queue[head];
  for (const next of graph[v]) {
    if (depth[next] !== -1) continue;
    depth[next] = depth[v] + 1;
    up[0][next] = v;
    queue.push(next);
  }
}
// up[k][v] = v から 2^k 個上の祖先（ダブリング）
for (let k = 1; k < LOG; k++) {
  for (let v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];
}

function lca(a: number, b: number): number {
  if (depth[a] < depth[b]) [a, b] = [b, a];
  // 深さをそろえる
  for (let k = LOG - 1; k >= 0; k--) {
    if (depth[a] - (1 << k) >= depth[b]) a = up[k][a];
  }
  if (a === b) return a;
  // 祖先が分かれる直前まで、2 つ同時に上げる
  for (let k = LOG - 1; k >= 0; k--) {
    if (up[k][a] !== up[k][b]) {
      a = up[k][a];
      b = up[k][b];
    }
  }
  return up[0][a];
}

const q = Number(input[n]);
const out: number[] = [];
for (let i = 0; i < q; i++) {
  const [a, b] = input[n + 1 + i].split(" ").map(Number);
  out.push(depth[a] + depth[b] - 2 * depth[lca(a, b)]);
}
console.log(out.join("\n"));
